#include <stdio.h>
#include <string.h>
#include <stdlib.h>
// gen N MODE PREFIX  : MODE U=upper L=lower C=capitalized
int main(int argc,char**argv){
  int n=atoi(argv[1]); char mode=argv[2][0];
  char pre[32]; pre[0]=0; if(argc>3) strncpy(pre,argv[3],31);
  int pl=strlen(pre);
  char base = (mode=='U')?'A':'a';
  // adjust prefix casing
  for(int i=0;i<pl;i++){
    if(mode=='U') pre[i]=pre[i]-'a'*(pre[i]>='a')+ (pre[i]>='a'?'A':0);
    else if(mode=='L') pre[i]= (pre[i]>='A'&&pre[i]<='Z')?pre[i]+32:pre[i];
    else { if(i==0) pre[i]=(pre[i]>='a')?pre[i]-32:pre[i]; else pre[i]=(pre[i]<='Z')?pre[i]+32:pre[i]; }
  }
  int rem=n-pl;
  if(rem<0) return 0;
  int idx[32]; for(int i=0;i<rem;i++) idx[i]=0;
  char word[64];
  memcpy(word,pre,pl);
  static char buf[1<<22]; size_t bl=0; int cnt=0;
  while(1){
    for(int i=0;i<rem;i++){
      char c = base + idx[i];
      if(mode=='C'){ if(pl==0 && i==0) c='A'+idx[i]; else c='a'+idx[i]; }
      word[pl+i]=c;
    }
    word[n]=0;
    memcpy(buf+bl,word,n); bl+=n;
    cnt++;
    if(cnt==400){ buf[bl++]='\n'; cnt=0; } else buf[bl++]=' ';
    if(bl > (1<<22)-256){ fwrite(buf,1,bl,stdout); bl=0; }
    int p=rem-1;
    while(p>=0){ idx[p]++; if(idx[p]<26) break; idx[p]=0; p--; }
    if(p<0) break;
  }
  if(cnt) buf[bl++]='\n';
  fwrite(buf,1,bl,stdout);
  return 0;
}
EOF
