#include <stdio.h>
#include <string.h>
#include <stdlib.h>
/* gen2 ALPHABET N PREFIX */
int main(int argc,char**argv){
  const char*A=argv[1]; int na=strlen(A);
  int n=atoi(argv[2]);
  char pre[32]; pre[0]=0; if(argc>3) strncpy(pre,argv[3],31);
  int pl=strlen(pre); int rem=n-pl; if(rem<0) return 0;
  int idx[32]; for(int i=0;i<rem;i++) idx[i]=0;
  char word[64]; memcpy(word,pre,pl);
  static char buf[1<<22]; size_t bl=0; int cnt=0;
  while(1){
    for(int i=0;i<rem;i++) word[pl+i]=A[idx[i]];
    memcpy(buf+bl,word,n); bl+=n; cnt++;
    if(cnt==400){ buf[bl++]='\n'; cnt=0; } else buf[bl++]=' ';
    if(bl > (1<<22)-256){ fwrite(buf,1,bl,stdout); bl=0; }
    int p=rem-1;
    while(p>=0){ idx[p]++; if(idx[p]<na) break; idx[p]=0; p--; }
    if(p<0) break;
  }
  if(cnt) buf[bl++]='\n';
  fwrite(buf,1,bl,stdout); return 0;
}
